package com.sphere.core.clhep.geometry;

/**
 * CLHEP's HepGeom::Normal3D&lt;float&gt; (Geometry/Normal3D.h, Normal3D.cc): the normal of a surface, which a
 * transformation turns by the cofactors of its matrix (normals stay normal under scaling). Generated by
 * gen_geometry.py.
 */
public class Normal3DF extends BasicVector3DF {

    public Normal3DF() {
        super();
    }

    public Normal3DF(float x1, float y1, float z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Normal3DF(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Normal3DF(BasicVector3DF v) {
        super(v);
    }

    /** This normal transformed by m: the cofactor matrix of m's 3x3 part. */
    public Normal3DF transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        final double xx = m.xx(), xy = m.xy(), xz = m.xz();
        final double yx = m.yx(), yy = m.yy(), yz = m.yz();
        final double zx = m.zx(), zy = m.zy(), zz = m.zz();
        set((float) ((yy * zz - yz * zy) * vx + (yz * zx - yx * zz) * vy + (yx * zy - yy * zx) * vz),
            (float) ((zy * xz - zz * xy) * vx + (zz * xx - zx * xz) * vy + (zx * xy - zy * xx) * vz),
            (float) ((xy * yz - xz * yy) * vx + (xz * yx - xx * yz) * vy + (xx * yy - xy * yx) * vz));
        return this;
    }
}
